  sosa:madeBySensor <VCAB-DP1-BP-40> ; 
  sosa:hasFeatureOfInterest  <VCAB-DP1-BP-40#location> ;
  sosa:observedProperty  <VCAB-DP1-BP-40#groundDisplacementSpeed> ;
